import java.util.ArrayList;
import java.util.List;

/**
 * Tower of Hanoi solver.
 * Prints each move in the format: "Move disk <k> from <src> to <dst>"
 * where disks are numbered 1 (smallest) to n (largest).
 */
public final class TowerOfHanoi {

    /**
     * Recursive core that performs the moves and records them.
     *
     * @param n     number of disks to move
     * @param src   source peg identifier
     * @param aux   auxiliary peg identifier
     * @param dst   destination peg identifier
     * @param moves list to which each move is appended
     */
    private static void hanoi(int n, char src, char aux, char dst, List<String> moves) {
        if (n == 0) {
            return;
        }
        // Move n-1 disks from src to aux, using dst as temporary
        hanoi(n - 1, src, dst, aux, moves);
        // Move the largest disk from src to dst
        moves.add(String.format("Move disk %d from %c to %c", n, src, dst));
        // Move n-1 disks from aux to dst, using src as temporary
        hanoi(n - 1, aux, src, dst, moves);
    }

    /**
     * Public façade that returns the sequence of moves for n disks.
     *
     * @param n number of disks (must be non‑negative)
     * @return list of move descriptions in order
     * @throws IllegalArgumentException if n < 0
     */
    public static List<String> solve(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Number of disks cannot be negative");
        }
        List<String> moves = new ArrayList<>( (1 << n) - 1 ); // pre‑allocate capacity 2^n‑1
        hanoi(n, 'A', 'B', 'C', moves);
        return moves;
    }

    /**
     * Demo driver: solves the puzzle for a given n and prints the moves.
     *
     * @param args command‑line arguments; first argument optionally specifies n
     */
    public static void main(String[] args) {
        int n = 3; // default
        if (args.length > 0) {
            try {
                n = Integer.parseInt(args[0]);
            } catch (NumberFormatException e) {
                System.err.println("Invalid integer argument: " + args[0]);
                System.exit(1);
            }
        }
        List<String> solution = solve(n);
        System.out.printf("Tower of Hanoi solution for %d disks (%d moves):%n", n, solution.size());
        for (String move : solution) {
            System.out.println(move);
        }
    }
}
```

